// Vereinheitlicht beide Trigger-Pfade auf ein gemeinsames Item mit
// DRY_RUN (Default false bei eigenstaendigem Zeitplan-Lauf).
// REQUIRE_CONFIRMATION kommt zentral aus trading.pipeline_config (siehe
// Node Kontext ergaenzen), nicht mehr als Konstante hier.
// Eingabe kommt seit Prioritaet 7/18 verschachtelt als {context, config, payload}.
const j = $json || {};
const ctx = j.context || {};
const cfg = j.config || {};
return [{ json: {
  run_id: ctx.run_id || ('standalone-' + Date.now()),
  _run_started_at: new Date().toISOString(),
  DRY_RUN: cfg.DRY_RUN === true || cfg.DRY_RUN === 'true'
} }];

// EMPFEHLUNGEN: NEWS+SIGNAL-ABGLEICH – Run Once for All Items
// Kombiniert starke News (wirkung_staerke=hoch) mit gleichgerichtetem technischem Signal.
// Bestehende offene Position + Gegensignal -> schliessen und ggf. neue Gegenrichtung oeffnen.
// Bestehende offene Position + gleiches Signal oder kein Signal -> keine Aktion.
//
// Welle 1 (2026-07-31), Arbeitspaket 5+6+7: alle 12 im Auftrag geforderten harten
// Vetos strukturiert (statt nur console.warn), deterministisches Einzeltrade-
// Risikomodell (AP6), deterministische These/Zeitstop je Strategie (AP7).
// Hart vetoete Oeffnungs-/Schliessungsversuche werden NICHT mehr nur geloggt,
// sondern als eigener _aktion='veto_log'-Item-Typ ausgegeben und in
// trading.recommendation_veto_log geschrieben (siehe "IF: Aktion = veto_log?").
// Schliessungen werden NIE durch ein Datenqualitaetsproblem vollstaendig
// blockiert (Auftragsvorgabe) - stattdessen sicherer Fallback auf den letzten
// bekannten gueltigen Kurs, mit explizitem Vermerk.

function getBusinessDate(date = new Date()) {
  return new Intl.DateTimeFormat('sv-SE', {
    timeZone: 'Europe/Berlin',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  }).format(date);
}
const heute = getBusinessDate();
const zeitstempel = new Date().toISOString();
const _triggerCtx = $('Kontext ergaenzen').all()[0];
const DRY_RUN = _triggerCtx && _triggerCtx.json ? _triggerCtx.json.DRY_RUN : false;
const REQUIRE_CONFIRMATION = _triggerCtx && _triggerCtx.json ? _triggerCtx.json.REQUIRE_CONFIRMATION : false;
const run_id = _triggerCtx && _triggerCtx.json ? _triggerCtx.json.run_id : null;
const TREND_KONFLIKT_SCHWELLE = _triggerCtx && _triggerCtx.json && !isNaN(Number(_triggerCtx.json.TREND_KONFLIKT_SCHWELLE)) ? Number(_triggerCtx.json.TREND_KONFLIKT_SCHWELLE) : 10;

// Welle 1, AP6: Risikomodell-Konfiguration aus trading.pipeline_config (ueber
// "Kontext ergaenzen" durchgereicht, gleiches Muster wie TREND_KONFLIKT_SCHWELLE).
// Konservative Defaults greifen, falls ein Wert (noch) nicht gesetzt ist.
const cfgNum = (key, fallback) => {
  const v = _triggerCtx && _triggerCtx.json ? _triggerCtx.json[key] : undefined;
  return v !== undefined && v !== null && !isNaN(Number(v)) ? Number(v) : fallback;
};
const RISK_CFG = {
  MODEL_PORTFOLIO_VALUE: cfgNum('MODEL_PORTFOLIO_VALUE', 100000),
  MAX_RISK_PER_TRADE_PCT: cfgNum('MAX_RISK_PER_TRADE_PCT', 1.0),
  MIN_REWARD_RISK_RATIO: cfgNum('MIN_REWARD_RISK_RATIO', 1.5),
  MAX_POSITION_VALUE_PCT: cfgNum('MAX_POSITION_VALUE_PCT', 20.0),
  DEFAULT_SLIPPAGE_BPS: cfgNum('DEFAULT_SLIPPAGE_BPS', 10),
  DEFAULT_FEES_BPS: cfgNum('DEFAULT_FEES_BPS', 15),
  MAX_DATA_AGE_MINUTES: cfgNum('MAX_DATA_AGE_MINUTES', 1440)
};
const RISK_MODEL_VERSION = 'welle1-v1';
const THESIS_RULE_VERSION = 'welle1-v1';

const techRows = $('DB: Technische Signale laden (Empf.)').all().map(i => i.json || {});
const newsRows = $('DB: News laden (Empf., trading.*)').all().map(i => i.json || {});
const empfehlungRows = $('DB: Bestehende Empfehlungen laden').all().map(i => i.json || {});
const trendRows = $input.all().map(i => i.json || {});

// Welle 1, AP5, Veto 10 (Referenzmarkt erforderlich, aber nicht verfuegbar):
// vereinfacht auf systemweite Verfuegbarkeit der 02b-Marktkontext-Tagesdaten
// (nicht pro-Ticker-Referenzindex-Zuordnung - siehe docs/HARTE_VETOS.md fuer
// die begruendete Vereinfachung).
let marktkontextVerfuegbarHeute = true;
try {
  const mkRows = $('DB: Marktkontext heute (Empf.)').all();
  marktkontextVerfuegbarHeute = mkRows.length > 0 && !!(mkRows[0].json && mkRows[0].json.anzahl > 0);
} catch (e) {
  // Node nicht gefunden - sicherer Default TRUE (kein Falsch-Veto durch ein
  // reines Verdrahtungsproblem dieses einzelnen Zusatz-Checks).
}

// Welle 1, AP5, Veto 9 (Datenbankzugriff fehlgeschlagen): eine dieser drei
// Ladeoperationen sollte im Normalbetrieb NIE komplett leer sein (15 aktive
// Ticker, taeglicher Lauf). Ein leeres Ergebnis ist ein starkes Indiz fuer
// einen fehlgeschlagenen/abgebrochenen DB-Zugriff weiter oben in der Kette,
// nicht fuer "heute zufaellig keine Kandidaten". Blockiert NUR neue
// Eroeffnungen (Schliessungen bleiben ueber den Fallback-Pfad moeglich).
const dbLesefehler = techRows.length === 0 || trendRows.length === 0;

const trendByTicker = {};
for (const r of trendRows) {
  const k = String(r.ticker || '').trim();
  if (!k) continue;
  if (!trendByTicker[k]) trendByTicker[k] = [];
  trendByTicker[k].push(r);
}
for (const k of Object.keys(trendByTicker)) trendByTicker[k].sort((a, b) => String(a.snapshot_date).localeCompare(String(b.snapshot_date)));

function trendInfo(ticker) {
  const arr = trendByTicker[String(ticker || '').trim()] || [];
  if (arr.length < 2) return { richtung: 'unbekannt', punkte: arr.length, delta: 0 };
  const erstRsi = Number(arr[0].rsi);
  const letztRsi = Number(arr[arr.length - 1].rsi);
  if (isNaN(erstRsi) || isNaN(letztRsi)) return { richtung: 'unbekannt', punkte: arr.length, delta: 0 };
  const delta = letztRsi - erstRsi;
  let richtung = 'seitwaerts';
  if (delta > 1) richtung = 'steigend';
  else if (delta < -1) richtung = 'fallend';
  return { richtung, punkte: arr.length, delta };
}

function atrInfo(ticker) {
  const arr = trendByTicker[String(ticker || '').trim()] || [];
  if (arr.length === 0) return { verfuegbar: false, atr: null, stop: null, target: null };
  const letzter = arr[arr.length - 1];
  const atr = Number(letzter.atr_14_numeric);
  if (letzter.atr_14_numeric == null || isNaN(atr) || atr <= 0) {
    return { verfuegbar: false, atr: null, stop: null, target: null };
  }
  const stop = letzter.atr_stop_numeric != null ? Number(letzter.atr_stop_numeric) : null;
  const target = letzter.atr_target_numeric != null ? Number(letzter.atr_target_numeric) : null;
  return { verfuegbar: true, atr, stop, target };
}

// Welle 1, AP2+AP3+AP4: Datenqualitaet/Mindesthistorie/Sitzungsstatus aus
// derselben bereits geladenen trendByTicker-Quelle (letzte Zeile = heutiger
// Lauf von "02", extended query siehe "DB: Trend-Signale laden (Empf.)").
function qualityInfo(ticker) {
  const arr = trendByTicker[String(ticker || '').trim()] || [];
  if (arr.length === 0) return { dataQualityStatus: 'unknown', breakoutHistoryAusreichend: null, dominantStrategy: null, sessionStatus: 'unknown' };
  const letzter = arr[arr.length - 1];
  return {
    dataQualityStatus: letzter.data_quality_status || 'unknown',
    breakoutHistoryAusreichend: letzter.breakout_history_ausreichend === true || letzter.breakout_history_ausreichend === 'true',
    dominantStrategy: letzter.dominant_strategy || null,
    sessionStatus: letzter.session_status || 'unknown'
  };
}

// Letzter bekannter GUELTIGER Kurs je Ticker (fuer den Schliessungs-Fallback,
// wenn der heutige Kurs fehlt/ungueltig ist) - neuester Eintrag mit einer
// verwertbaren aktueller_kurs-Zahl in den letzten 5 Handelstagen.
function letzterGueltigerKurs(ticker) {
  const arr = trendByTicker[String(ticker || '').trim()] || [];
  for (let i = arr.length - 1; i >= 0; i--) {
    const v = Number(arr[i].aktueller_kurs);
    if (!isNaN(v) && v > 0) return { kurs: v, datum: arr[i].snapshot_date };
  }
  return null;
}

function veto(code, source, message, observed, required) {
  return { code, severity: 'hard', source, message, observed_value: observed, required_value: required };
}

// Welle 1, AP6: deterministisches Einzeltrade-Risikomodell. Formel exakt wie
// im Auftrag. Liefert null, wenn unit_risk<=0 oder theoretische Stueckzahl 0.
function computeRisk(entry, stop, target) {
  const unitRisk = Math.abs(entry - stop);
  if (!(unitRisk > 0)) return null;
  const riskAmount = RISK_CFG.MODEL_PORTFOLIO_VALUE * (RISK_CFG.MAX_RISK_PER_TRADE_PCT / 100);
  const theoreticalQuantity = Math.floor(riskAmount / unitRisk);
  const positionValue = theoreticalQuantity * entry;
  const positionValuePct = RISK_CFG.MODEL_PORTFOLIO_VALUE > 0 ? (positionValue / RISK_CFG.MODEL_PORTFOLIO_VALUE) * 100 : null;
  const rewardRiskRatio = Math.abs(target - entry) / unitRisk;
  const estimatedFees = positionValue * (RISK_CFG.DEFAULT_FEES_BPS / 10000);
  const estimatedSlippage = positionValue * (RISK_CFG.DEFAULT_SLIPPAGE_BPS / 10000);
  const maxPlannedLoss = unitRisk * theoreticalQuantity + estimatedFees + estimatedSlippage;
  return {
    riskAmount: parseFloat(riskAmount.toFixed(2)),
    unitRisk: parseFloat(unitRisk.toFixed(4)),
    theoreticalQuantity,
    positionValue: parseFloat(positionValue.toFixed(2)),
    positionValuePct: positionValuePct !== null ? parseFloat(positionValuePct.toFixed(4)) : null,
    rewardRiskRatio: parseFloat(rewardRiskRatio.toFixed(4)),
    estimatedFees: parseFloat(estimatedFees.toFixed(2)),
    estimatedSlippage: parseFloat(estimatedSlippage.toFixed(2)),
    maxPlannedLoss: parseFloat(maxPlannedLoss.toFixed(2))
  };
}

// Welle 1, AP7: deterministische These/Zeitstop je Strategie - die KI legt
// die Zeitpunkte NICHT frei fest, die Regeln sind hier fest kodiert und
// versioniert (THESIS_RULE_VERSION).
function computeThesis(strategy, ticker, richtung, evidenceText) {
  let s = strategy;
  let horizonDays;
  let invalidation;
  if (s === 'mean_reversion') { horizonDays = 3; invalidation = ['RSI kehrt in neutrale Zone (38-62) zurueck', 'Kurs verlaesst Bollinger-Band-Extrembereich']; }
  else if (s === 'trend_following') { horizonDays = 15; invalidation = ['MACD-Kreuzung gegen die Positionsrichtung', 'Kurs wechselt die Seite von EMA20']; }
  else if (s === 'breakout') { horizonDays = 7; invalidation = ['Kurs faellt/steigt zurueck unter/ueber das Ausbruchsniveau (Fehlausbruch)']; }
  else { s = 'news_event'; horizonDays = 2; invalidation = ['Gegenteilige starke Nachricht am selben oder Folgetag']; }
  const now = new Date();
  const createdAt = now.toISOString();
  const timeStopAt = new Date(now.getTime() + horizonDays * 86400000).toISOString();
  const thesis = (ticker + ' ' + (richtung === 'kauf' ? 'Long' : 'Short') + '-These (' + s + '): ' + evidenceText).slice(0, 480);
  return {
    strategy: s, tradeThesis: thesis, thesisCreatedAt: createdAt,
    timeStopAt, thesisExpiresAt: timeStopAt, expectedHorizonDays: horizonDays,
    invalidationConditions: invalidation, ruleVersion: THESIS_RULE_VERSION
  };
}

// Ticker->Sektor + heutige Signale
const tickerSektorMap = {};
const signalByTicker = {};
for (const s of techRows) {
  if (!s.ticker) continue;
  if (s.sektor) tickerSektorMap[String(s.ticker).trim()] = String(s.sektor).trim();
  if (String(s.datum || '').startsWith(heute)) {
    signalByTicker[String(s.ticker).trim()] = {
      ticker: String(s.ticker).trim(),
      name: s.name || '',
      sektor: s.sektor || '',
      aktueller_kurs: s.aktueller_kurs,
      handels_status: s.handels_status || '',
      richtung: s.richtung || ''
    };
  }
}

// Sektor-Schluesselwoerter (gleiche Liste wie im Tagesreport)
const SEKTOR_KEYWORDS = {
  'Auto':         ['auto', 'automobil', 'fahrzeug', 'e-auto', 'elektroauto', 'zulieferer', 'pkw'],
  'Energie':      ['energie', 'strom', 'gas', 'öl', 'ölpreis', 'kraftwerk', 'erneuerbare'],
  'Chemie':       ['chemie', 'chemiekonzern', 'chemieindustrie'],
  'Banken':       ['bank', 'banken', 'zins', 'zinsen', 'ezb', 'kredit', 'finanzsektor'],
  'Pharma':       ['pharma', 'medikament', 'arznei', 'biotech', 'arzneimittel'],
  'Telekom':      ['telekom', 'mobilfunk', '5g', 'netzausbau', 'glasfaser'],
  'Versicherung': ['versicherung', 'versicherer'],
  'Technologie':  ['software', 'chip', 'halbleiter', ' ki ', 'cloud', 'tech-branche'],
  'Industrie':    ['industrie', 'maschinenbau', 'anlagenbau', 'industriekonzern'],
  'Sport':        ['sportartikel', 'sportbekleidung'],
  'Konsumgüter':  ['konsumgüter', 'konsumgüterkonzern'],
  'Gesundheit':   ['gesundheitswesen', 'klinik', 'medizintechnik']
};

function sektorenAusText(text) {
  const t = String(text || '').toLowerCase();
  return Object.entries(SEKTOR_KEYWORDS)
    .filter(([, keywords]) => keywords.some(k => t.includes(k)))
    .map(([sektor]) => sektor);
}

function tickerAusNews(n) {
  const genannt = Array.isArray(n.betroffene_ticker_json) ? n.betroffene_ticker_json : [];
  if (n.wirkungsebene !== 'sektor') return genannt;
  const matchText = [n.titel, n.wirkungs_begruendung, n.ticker_begruendung].filter(Boolean).join(' ');
  const sektoren = sektorenAusText(matchText);
  const sektorTicker = Object.entries(tickerSektorMap)
    .filter(([, sektor]) => sektoren.includes(sektor))
    .map(([ticker]) => ticker);
  return Array.from(new Set([...genannt, ...sektorTicker]));
}

// Starke News von heute je Ticker sammeln, inkl. juengstem published_at fuer
// den Welle-1-Veto "Nachricht zu alt fuer die Strategie" (AP5, Veto 3).
const newsRichtungByTicker = {};
const newsGrundByTicker = {};
const newsPublishedAtByTicker = {};
const widerspruechlich = new Set();

for (const n of newsRows) {
  if (n.wirkung_staerke !== 'hoch') continue;
  if (n.wirkungsrichtung !== 'positiv' && n.wirkungsrichtung !== 'negativ') continue;

  const ticker = tickerAusNews(n);
  for (const t of ticker) {
    if (!signalByTicker[t]) continue;
    const bisherige = newsRichtungByTicker[t];
    if (bisherige && bisherige !== n.wirkungsrichtung) {
      widerspruechlich.add(t);
      console.warn(`[Welle 1 Veto WIDERSPRUECHLICHE_NEWS] ${t}: widerspruechliche starke News am selben Tag (${bisherige} vs. ${n.wirkungsrichtung}).`);
      continue;
    }
    newsRichtungByTicker[t] = n.wirkungsrichtung;
    if (!newsGrundByTicker[t]) newsGrundByTicker[t] = [];
    newsGrundByTicker[t].push(String(n.titel || '').slice(0, 120));
    const pub = n.published_at ? new Date(n.published_at).getTime() : null;
    if (pub && (!newsPublishedAtByTicker[t] || pub > newsPublishedAtByTicker[t])) newsPublishedAtByTicker[t] = pub;
  }
}

// Kombiniertes Signal je Ticker bestimmen
const kandidatenStatus = new Set(['handelskandidat', 'beobachten']);
const combinedByTicker = {};

for (const [ticker, newsRichtung] of Object.entries(newsRichtungByTicker)) {
  if (widerspruechlich.has(ticker)) continue;
  const signal = signalByTicker[ticker];
  if (!signal || !kandidatenStatus.has(signal.handels_status)) continue;

  if (newsRichtung === 'positiv' && signal.richtung === 'long') {
    combinedByTicker[ticker] = 'kauf';
  } else if (newsRichtung === 'negativ' && signal.richtung === 'short') {
    combinedByTicker[ticker] = 'verkauf';
  }
}

// Bestehende offene Positionen indexieren
const offenByTicker = {};
for (const row of empfehlungRows) {
  if (row.status === 'offen' && row.ticker) {
    offenByTicker[String(row.ticker).trim()] = row;
  }
}

// Onvista-Slug je Ticker fuer den generischen Knock-Out-Finder-Link.
const ONVISTA_SLUGS = {
  'SAP.DE': 'SAP', 'SIE.DE': 'Siemens', 'BASF.DE': 'BASF', 'ALV.DE': 'Allianz',
  'MBG.DE': 'Mercedes-Benz-Group-Daimler', 'BMW.DE': 'BMW', 'VOW3.DE': 'Volkswagen-VZ',
  'DBK.DE': 'Deutsche-Bank', 'DTE.DE': 'Deutsche-Telekom', 'RWE.DE': 'RWE',
  'BAYN.DE': 'Bayer', 'EOAN.DE': 'EON', 'ADS.DE': 'Adidas', 'HEN3.DE': 'Henkel', 'FRE.DE': 'Fresenius'
};

function hebelHinweis(ticker, aktuellerKurs, richtung) {
  const kurs = Number(aktuellerKurs);
  const slug = ONVISTA_SLUGS[ticker] || null;
  const link = slug ? `https://www.onvista.de/derivate/Knock-Outs/Knock-Outs-auf-${slug}` : '';
  if (isNaN(kurs) || kurs <= 0) {
    return { typ: '', spanne: '', basis3: null, basis4: null, link, text: '' };
  }
  const typ = richtung === 'kauf' ? 'Long Mini-Future' : 'Short Mini-Future';
  const basis3Raw = richtung === 'kauf' ? kurs * (1 - 1 / 3) : kurs * (1 + 1 / 3);
  const basis4Raw = richtung === 'kauf' ? kurs * (1 - 1 / 4) : kurs * (1 + 1 / 4);
  const basis3 = parseFloat(basis3Raw.toFixed(2));
  const basis4 = parseFloat(basis4Raw.toFixed(2));
  const linkHinweis = link
    ? ` Passende Produktliste (bitte dort auf Hebel 3-4 und ${richtung === 'kauf' ? 'Long' : 'Short'} filtern): ${link}`
    : '';
  const text = `${typ}, Hebel 3-4x (nicht mehr). Rechnerischer Basispreis-Richtwert: ca. ${basis4} EUR (Hebel 4) bis ${basis3} EUR (Hebel 3). Kein konkretes Produkt -${linkHinweis} Emittent/Spread/Finanzierungskosten selbst pruefen.`;
  return { typ, spanne: '3x-4x', basis3, basis4, link, text };
}

// Welle 1, AP5: zentrale Hart-Veto-Pruefung fuer eine geplante Eroeffnung.
// Prueft ALLE zutreffenden der 12 Auftrags-Vetos und liefert die vollstaendige
// Blocker-Liste (auch wenn mehrere gleichzeitig zutreffen - fuer Audit-Wert),
// plus die bereits berechneten Hilfswerte (atrInfo/risk/thesis-Basis), damit
// sie bei Erfolg direkt weiterverwendet werden koennen statt doppelt berechnet.
function pruefeOeffnungsVetos(ticker, richtung, signal) {
  const blockers = [];

  // Veto 1: Kursdaten fehlen oder sind ungueltig.
  const kursWert = Number(signal.aktueller_kurs);
  const kursUngueltig = signal.aktueller_kurs === null || signal.aktueller_kurs === undefined || signal.aktueller_kurs === '' || isNaN(kursWert) || kursWert <= 0;
  if (kursUngueltig) {
    blockers.push(veto('PRICE_MISSING', 'technical_signal', 'Kein gueltiger Referenzkurs vorhanden', signal.aktueller_kurs, '> 0'));
  }

  const qi = qualityInfo(ticker);
  // Veto 2: Datenqualitaet invalid/stale/session_incomplete.
  if (['invalid', 'stale', 'session_incomplete'].includes(qi.dataQualityStatus)) {
    blockers.push(veto('DATA_QUALITY', 'technical_signal', 'Datenqualitaet der Kurshistorie unzureichend fuer eine Eroeffnung', qi.dataQualityStatus, 'valid oder limited'));
  }

  // Veto 3: Nachricht ist fuer die Strategie zu alt (strategie-abhaengiger
  // deterministischer Schwellwert, gleiche Horizont-Logik wie AP7).
  const dominantStrategy = qi.dominantStrategy;
  const maxNewsAgeH = dominantStrategy === 'mean_reversion' ? 6 : dominantStrategy === 'breakout' ? 3 : dominantStrategy === 'trend_following' ? 24 : 12;
  const newsPub = newsPublishedAtByTicker[ticker];
  if (newsPub) {
    const ageH = (Date.now() - newsPub) / 3600000;
    if (ageH > maxNewsAgeH) {
      blockers.push(veto('NEWS_STALE', 'news', 'Ausloesende Nachricht ist fuer diese Strategie zu alt', Math.round(ageH * 10) / 10 + 'h', '<= ' + maxNewsAgeH + 'h'));
    }
  }

  // Veto 4: Stop/Ziel fehlen oder sind unplausibel (kein verwertbarer ATR).
  const atr = atrInfo(ticker);
  if (!atr.verfuegbar || atr.stop === null || atr.target === null) {
    blockers.push(veto('STOP_TARGET_INVALID', 'technical_signal', 'Kein verwertbarer ATR-basierter Stop/Ziel-Wert', atr.atr, '> 0'));
  }

  let stopWrongSide = false, targetWrongSide = false, rrrTooLow = false, risk = null;
  if (atr.verfuegbar && atr.stop !== null && atr.target !== null && !kursUngueltig) {
    // Veto 5+6: Stop/Ziel auf der falschen Seite des Einstiegs.
    if (richtung === 'kauf') {
      if (atr.stop >= kursWert) { stopWrongSide = true; blockers.push(veto('STOP_WRONG_SIDE', 'risk_model', 'Stop liegt bei einem Long-Setup nicht unterhalb des Einstiegs', atr.stop, '< ' + kursWert)); }
      if (atr.target <= kursWert) { targetWrongSide = true; blockers.push(veto('TARGET_WRONG_SIDE', 'risk_model', 'Ziel liegt bei einem Long-Setup nicht oberhalb des Einstiegs', atr.target, '> ' + kursWert)); }
    } else {
      if (atr.stop <= kursWert) { stopWrongSide = true; blockers.push(veto('STOP_WRONG_SIDE', 'risk_model', 'Stop liegt bei einem Short-Setup nicht oberhalb des Einstiegs', atr.stop, '> ' + kursWert)); }
      if (atr.target >= kursWert) { targetWrongSide = true; blockers.push(veto('TARGET_WRONG_SIDE', 'risk_model', 'Ziel liegt bei einem Short-Setup nicht unterhalb des Einstiegs', atr.target, '< ' + kursWert)); }
    }
    // Veto 7: Chance-Risiko-Verhaeltnis unterschreitet die Mindestgrenze.
    if (!stopWrongSide && !targetWrongSide) {
      risk = computeRisk(kursWert, atr.stop, atr.target);
      if (risk && risk.rewardRiskRatio < RISK_CFG.MIN_REWARD_RISK_RATIO) {
        rrrTooLow = true;
        blockers.push(veto('RRR_TOO_LOW', 'risk_model', 'Chance-Risiko-Verhaeltnis unterschreitet die konfigurierte Mindestgrenze', risk.rewardRiskRatio, '>= ' + RISK_CFG.MIN_REWARD_RISK_RATIO));
      }
    }
  }

  // Veto 9: Datenbankzugriff fehlgeschlagen (Lauf-Ebene, oben ermittelt).
  if (dbLesefehler) {
    blockers.push(veto('DB_ERROR', 'pipeline', 'Ein vorgelagerter Datenbankzugriff lieferte unerwartet keine Zeilen (vermutlich fehlgeschlagen)', 'leer', '> 0 Zeilen'));
  }

  // Veto 10: Referenzmarkt erforderlich, aber nicht verfuegbar (vereinfacht:
  // systemweite Verfuegbarkeit der Marktkontext-Tagesdaten aus "02b", nicht
  // pro-Ticker-Referenzindex-Zuordnung - siehe docs/HARTE_VETOS.md).
  if (!marktkontextVerfuegbarHeute) {
    blockers.push(veto('REFERENZMARKT_FEHLT', 'market_context', 'Marktkontext-Referenzdaten (02b) liegen fuer heute nicht vor', 'keine Zeilen', '>= 1 Zeile'));
  }

  // Veto 11: widersprüchliche starke News (bereits vorher gefiltert, hier nur
  // zur Vollstaendigkeit dokumentiert - combinedByTicker enthaelt diese
  // Ticker nie, dieser Zweig wird de facto nicht erreicht).
  if (widerspruechlich.has(ticker)) {
    blockers.push(veto('WIDERSPRUECHLICHE_NEWS', 'news', 'Widerspruechliche starke News am selben Tag', 'positiv und negativ', 'eindeutig'));
  }

  // Veto 12: Strategie benoetigt 252 Tage Historie, sind aber nicht verfuegbar.
  if (dominantStrategy === 'breakout' && qi.breakoutHistoryAusreichend === false) {
    blockers.push(veto('HISTORY_252_MISSING', 'technical_signal', 'Breakout-Signal ohne ausreichende 252-Tage-Historie (und ohne 52-Wochen-Meta-Wert)', 'unzureichend', '>= 252 Handelstage oder Meta-52-Wochen-Wert'));
  }

  return { blockers, atr, risk, dominantStrategy };
}

// Aktionen ableiten: oeffnen / schliessen+oeffnen (Gegensignal)
const output = [];

function buildOpenCandidate(ticker, richtung, signal, grundText, quelle) {
  const pruef = pruefeOeffnungsVetos(ticker, richtung, signal);
  if (pruef.blockers.length > 0) {
    console.warn(`[Welle 1] ${ticker}: Eroeffnung hart vetoet (${pruef.blockers.map(b => b.code).join(', ')})`);
    output.push({ json: { _aktion: 'veto_log', run_id, ticker, veto_action: 'oeffnen', blockers: pruef.blockers, DRY_RUN } });
    return;
  }
  const kursWert = Number(signal.aktueller_kurs);
  const risk = pruef.risk || computeRisk(kursWert, pruef.atr.stop, pruef.atr.target);
  // Veto-artige Bremse ohne harten Veto-Code: Positionsgroesse ueber dem
  // konfigurierten Maximalanteil wird gekappt (nicht blockiert) - Formel
  // erlaubt das, da theoretical_quantity abwaerts gerundet ist; ein zu hoher
  // Anteil ist ein Konfigurationsfall (kleines Portfolio, groesserer ATR-
  // Abstand), keine Datenqualitaetsfrage. Wird als informativer Blocker
  // vermerkt (severity 'soft'), nicht als harte Ablehnung.
  const softBlockers = [];
  if (risk && risk.positionValuePct !== null && risk.positionValuePct > RISK_CFG.MAX_POSITION_VALUE_PCT) {
    softBlockers.push({ code: 'POSITION_SIZE_HOCH', severity: 'soft', source: 'risk_model', message: 'Theoretische Positionsgroesse ueberschreitet MAX_POSITION_VALUE_PCT (informativ, nicht blockierend)', observed_value: risk.positionValuePct, required_value: '<= ' + RISK_CFG.MAX_POSITION_VALUE_PCT });
  }

  const trend = trendInfo(ticker);
  const trendKonflikt = (richtung === 'kauf' && trend.richtung === 'fallend') || (richtung === 'verkauf' && trend.richtung === 'steigend');
  const trendKonfliktStark = trendKonflikt && Math.abs(trend.delta) >= TREND_KONFLIKT_SCHWELLE;
  if (trendKonflikt) {
    softBlockers.push({ code: 'TREND_KONFLIKT', severity: 'soft', source: 'trend', message: 'RSI-5-Tage-Trend widerspricht dem Tagessignal', observed_value: trend.richtung, required_value: 'gleichgerichtet oder unbekannt' });
  }

  const hh = hebelHinweis(ticker, signal.aktueller_kurs, richtung);
  const thesis = computeThesis(pruef.dominantStrategy, ticker, richtung, grundText);

  // Selbst-Konsistenz-Pruefung (Teil von Veto 8 im Auftrag: "thesis_expires_at
  // fehlt oder ist bereits ueberschritten") - nach der eigenen Berechnung
  // oben duerfte das nie eintreten; wenn doch, ist das ein Bug in
  // computeThesis() und die Eroeffnung wird sicherheitshalber geblockt statt
  // eine kaputte These zu schreiben.
  if (!thesis.thesisExpiresAt || new Date(thesis.thesisExpiresAt).getTime() <= Date.now()) {
    output.push({ json: { _aktion: 'veto_log', run_id, ticker, veto_action: 'oeffnen', blockers: [veto('THESIS_INVALID', 'thesis_engine', 'Berechnete These/Zeitstop fehlt oder liegt bereits in der Vergangenheit', thesis.thesisExpiresAt, '> jetzt')], DRY_RUN } });
    return;
  }

  output.push({ json: {
    _aktion: 'oeffnen', _dry_run: DRY_RUN, _require_confirmation: REQUIRE_CONFIRMATION || trendKonfliktStark,
    _confirmation_reason: trendKonfliktStark ? ('Starker RSI-5-Tage-Gegentrend (' + trend.richtung + ', Δ' + trend.delta.toFixed(1) + ')') : (REQUIRE_CONFIRMATION ? 'REQUIRE_CONFIRMATION aktiv' : ''), run_id,
    ticker, name: signal.name, sektor: signal.sektor,
    richtung, entry_datum: heute, entry_kurs: signal.aktueller_kurs,
    entry_grund: '[SIMULATION - keine reale Order] ' + grundText, letzte_aktualisierung: zeitstempel,
    hebelprodukt_typ: hh.typ, hebel_spanne: hh.spanne,
    basispreis_hebel_3: hh.basis3, basispreis_hebel_4: hh.basis4,
    onvista_link: hh.link, hebelprodukt_hinweis: hh.text,
    stop_price: pruef.atr.stop, target_price: pruef.atr.target,
    decision_score: trendKonflikt ? 40 : (trend.richtung === 'unbekannt' ? 60 : 75),
    decision_blockers: softBlockers,
    market_regime: trend.richtung,
    is_theoretical: true,
    data_quality_score: null,
    // Welle 1, AP6: Einzeltrade-Risikomodell
    risk_amount: risk ? risk.riskAmount : null,
    unit_risk: risk ? risk.unitRisk : null,
    theoretical_quantity: risk ? risk.theoreticalQuantity : null,
    position_value: risk ? risk.positionValue : null,
    position_value_pct: risk ? risk.positionValuePct : null,
    reward_risk_ratio: risk ? risk.rewardRiskRatio : null,
    estimated_fees: risk ? risk.estimatedFees : null,
    estimated_slippage: risk ? risk.estimatedSlippage : null,
    max_planned_loss: risk ? risk.maxPlannedLoss : null,
    risk_model_version: RISK_MODEL_VERSION,
    // Welle 1, AP7: These/Zeitstop
    strategy: thesis.strategy,
    trade_thesis: thesis.tradeThesis,
    thesis_created_at: thesis.thesisCreatedAt,
    thesis_expires_at: thesis.thesisExpiresAt,
    expected_holding_days: thesis.expectedHorizonDays,
    time_stop_at: thesis.timeStopAt,
    invalidation_conditions_json: thesis.invalidationConditions,
    thesis_rule_version: thesis.ruleVersion
  }});
}

for (const [ticker, richtung] of Object.entries(combinedByTicker)) {
  const signal = signalByTicker[ticker];
  const offen = offenByTicker[ticker];
  const grund = `Kombiniertes Signal (${heute}): News ${newsRichtungByTicker[ticker]} + technisches Signal ${signal.richtung}/${signal.handels_status}. Anlass: ${(newsGrundByTicker[ticker] || []).join(' | ')}`;

  if (!offen) {
    buildOpenCandidate(ticker, richtung, signal, grund, 'kombiniertes_signal');
    continue;
  }

  if (offen.richtung === richtung) {
    continue;
  }

  // Welle 1, AP5: eine Schliessung darf NIE vollstaendig durch ein
  // Datenqualitaetsproblem verhindert werden. Fehlt/ist der heutige Kurs
  // ungueltig, faellt der Schliessungspfad auf den letzten bekannten
  // gueltigen Kurs der vergangenen 5 Handelstage zurueck und vermerkt das
  // explizit - statt die Schliessung stillschweigend zu unterlassen (das war
  // der Bug vor Welle 1: kursUngueltig blockierte bisher OEFFNEN UND
  // SCHLIESSEN gemeinsam).
  const kursWertHeute = Number(signal.aktueller_kurs);
  const kursHeuteUngueltig = signal.aktueller_kurs === null || signal.aktueller_kurs === undefined || signal.aktueller_kurs === '' || isNaN(kursWertHeute) || kursWertHeute <= 0;
  let exitKursWert = kursWertHeute;
  let exitDatenqualitaetHinweis = null;
  if (kursHeuteUngueltig) {
    const fallback = letzterGueltigerKurs(ticker);
    if (fallback) {
      exitKursWert = fallback.kurs;
      exitDatenqualitaetHinweis = `Heutiger Kurs ungueltig - Schliessung mit letztem bekannten gueltigen Kurs vom ${fallback.datum} (Datenqualitaets-Fallback, sicherer Schliessungspfad statt Blockade).`;
      console.warn(`[Welle 1] ${ticker}: Schliessung mit Datenqualitaets-Fallback (${fallback.datum}: ${fallback.kurs}) statt Blockade.`);
    } else {
      exitDatenqualitaetHinweis = 'Weder heutiger noch ein bekannter gueltiger Kurs der letzten 5 Handelstage vorhanden - Schliessung ohne Performance-Berechnung durchgefuehrt (manuelle Pruefung empfohlen).';
      console.warn(`[Welle 1] ${ticker}: Schliessung OHNE jeden verwertbaren Kurs - Performance bleibt leer, manuelle Pruefung empfohlen.`);
    }
  }

  const entryKurs = Number(offen.entry_kurs);
  let performancePct = null;
  if (!isNaN(entryKurs) && exitKursWert !== null && !isNaN(exitKursWert) && entryKurs > 0) {
    performancePct = offen.richtung === 'kauf'
      ? ((exitKursWert - entryKurs) / entryKurs) * 100
      : ((entryKurs - exitKursWert) / entryKurs) * 100;
    performancePct = parseFloat(performancePct.toFixed(2));
  }

  output.push({ json: {
    _aktion: 'schliessen', run_id, _dry_run: DRY_RUN, _require_confirmation: REQUIRE_CONFIRMATION,
    ticker, _existing_id: offen.id,
    exit_datum: heute, exit_kurs: exitKursWert,
    exit_grund: `[SIMULATION] Gegensignal: ${grund}` + (exitDatenqualitaetHinweis ? ' | ' + exitDatenqualitaetHinweis : ''),
    performance_pct: performancePct,
    letzte_aktualisierung: zeitstempel
  }});

  // Neueroeffnung in Gegenrichtung nach der Schliessung: unterliegt denselben
  // harten Vetos wie eine frische Eroeffnung (nutzt den heutigen Kurs, nicht
  // den Fallback - eine neue Position braucht einen echten aktuellen Kurs).
  if (!kursHeuteUngueltig) {
    buildOpenCandidate(ticker, richtung, signal, grund, 'kombiniertes_signal_nach_schliessung');
  } else {
    console.warn(`[Welle 1] ${ticker}: Neueroeffnung nach Schliessung uebersprungen (kein gueltiger heutiger Kurs fuer eine NEUE Position - der Fallback gilt nur fuer die Schliessung der ALTEN Position).`);
  }
}

return output;

