const cfgNumByKey = {};
for (const r of cfgRows) { cfgByKey[r.config_key] = r.value_bool; cfgNumByKey[r.config_key] = r.value_numeric; }
const requireConfirmation = cfgByKey.hasOwnProperty('REQUIRE_CONFIRMATION') ? cfgByKey.REQUIRE_CONFIRMATION : true;
const dryRun = base.DRY_RUN === true ? true : (cfgByKey.hasOwnProperty('DRY_RUN') ? cfgByKey.DRY_RUN : false);
// Nutzerentscheidung 2026-07-28: 5-Tage-RSI-Trend darf die Kauf-/Verkauf-Entscheidung in
// "Empfehlungen: Abgleich berechnen" blockieren, aber nur bei STARKEM Gegen-Trend - Schwelle
