const trendKonfliktSchwelleRaw = cfgNumByKey['TREND_KONFLIKT_SCHWELLE'];
const trendKonfliktSchwelle = trendKonfliktSchwelleRaw !== undefined && trendKonfliktSchwelleRaw !== null && !isNaN(Number(trendKonfliktSchwelleRaw)) ? Number(trendKonfliktSchwelleRaw) : 10;
// Welle 1, AP6: Risikomodell-Konfiguration durchreichen (gleiches Muster wie
