  MAX_POSITION_VALUE_PCT: 20.0, DEFAULT_SLIPPAGE_BPS: 10, DEFAULT_FEES_BPS: 15, MAX_DATA_AGE_MINUTES: 1440
};
const riskCfgOut = {};
for (const [key, fallback] of Object.entries(RISK_KEYS_DEFAULTS)) {
  const raw = cfgNumByKey[key];
  riskCfgOut[key] = raw !== undefined && raw !== null && !isNaN(Number(raw)) ? Number(raw) : fallback;
}

return [{ json: { ...base, DRY_RUN: dryRun, REQUIRE_CONFIRMATION: requireConfirmation, TREND_KONFLIKT_SCHWELLE: trendKonfliktSchwelle, ...riskCfgOut } }];

const items = $input.all().map(i => i.json);
const planned_actions = items.map(it => ({
  ticker: it.ticker || null,
