    return { json: { ...base, _aktion: 'oeffnen', _write_failed: true, _write_error: errMsg } };
  }
  return { json: { ...j, _aktion: 'oeffnen', _write_failed: false, _write_error: null } };
});

return $input.all().map((i, idx) => {
